import http.client,json,ssl
from urllib.parse import urlsplit

def request(config,method,path,data=None,bearer=None):
    with open(config,encoding="utf8") as stream:settings=json.load(stream)
    server=urlsplit(settings["server"])
    if server.scheme!="https" or server.hostname!="127.0.0.1" or not path.startswith("/"):raise ValueError("private fixture only")
    context=ssl.create_default_context(cafile=settings["ca"])
    if bearer is None:context.load_cert_chain(settings["cert"],settings["key"])
    connection=http.client.HTTPSConnection(server.hostname,server.port,context=context,timeout=5)
    headers={"Content-Type":"application/json"}
    if bearer is not None:headers["Authorization"]="Bearer "+bearer
    try:
        connection.request(method,path,json.dumps(data).encode() if data is not None else None,headers)
        response=connection.getresponse();raw=response.read();status=response.status
    finally:connection.close()
    try:return status,json.loads(raw)
    except ValueError:return status,raw.decode(errors="replace")
